const data = $input.first().json;

const chunks = Array.isArray(data.chunks) ? data.chunks : [];

function cleanString(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function cleanNullableNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function cleanAssetArray(value, nameKey, pathKey) {
  if (!Array.isArray(value)) return [];

  return value
    .map((item, fallbackIndex) => {
      if (!item || typeof item !== 'object' || Array.isArray(item)) return null;

      const path = cleanString(item[pathKey]);
      if (!path) return null;

      const indexNumber = Number(item.index);
      return {
        index: Number.isFinite(indexNumber) ? indexNumber : fallbackIndex,
        [nameKey]: cleanString(item[nameKey]) || path,
        [pathKey]: path,
      };
    })
    .filter(Boolean);
}

const items = chunks
  .map((chunk) => ({
    chunk_id: cleanString(chunk.chunk_id),
    content: cleanString(chunk.content),
    content_text: cleanString(chunk.content),
    chunk_index: cleanNullableNumber(chunk.chunk_index),
    chunk_type: cleanString(chunk.chunk_type),
    file_name: cleanString(chunk.file_name),
    file_path: cleanString(chunk.file_path),
    path: cleanString(chunk.path),
    imgs: cleanAssetArray(chunk.imgs, 'img_name', 'img_path'),
    links: cleanAssetArray(chunk.links, 'link_name', 'link_path'),
  }))
  .filter((item) => item.chunk_id && item.content_text);

return items.map((item) => ({
  json: item,
}));
